package com.bank.codeanalyzer;

import java.util.*;
import java.util.logging.*;

public class FirstUniqueDemo {
    private static final Logger log = Logger.getLogger("CodeAnalyzer");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        CodeAnalyzer analyzer = new CodeAnalyzer();
        log.info(() -> "swiss → " + analyzer.firstNonRepeating("swiss"));   // 'w'
        log.info(() -> "aabb  → " + analyzer.firstNonRepeating("aabb"));    // none
    }
}

// ─── Would be in service/CodeAnalyzer.java ───
class CodeAnalyzer {
    Optional<Character> firstNonRepeating(String s) {
        Map<Character, Long> counts = s.chars()                 // IntStream of code points
            .mapToObj(c -> (char) c)                            // → Character
            .collect(java.util.stream.Collectors.groupingBy(
                ch -> ch,
                LinkedHashMap::new,                              // preserve first-seen order
                java.util.stream.Collectors.counting()));
        return counts.entrySet().stream()
            .filter(e -> e.getValue() == 1L)                    // appears exactly once
            .map(Map.Entry::getKey)
            .findFirst();                                        // earliest such char
    }
}
